{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "In monkeys, mithramycin—a large polyhydroxylated glycoside—showed a peak CSF:plasma ratio of only 0.12 and little material in normal brains, directly demonstrating poor CNS access for a structurally related glycoside.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Navtemadlin had Kp_brain = 0.009 in mice, with exclusion mediated primarily by P-gp efflux, showing that transporter-mediated exclusion can dominate even for molecules with otherwise drug-like features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Digitoxin exhibited a very low CSF/plasma ratio (0.01–0.03) in dogs, indicating that cardiac glycosides do not easily penetrate the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "DIFEQ, a polyphenolic glycoside, showed brain uptake of only 0.003% of the injected dose in mice, consistent with poor brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Gentamicin, an amino-sugar-containing antibiotic, produced no detectable or adequate CSF levels after systemic administration in humans and animals, supporting poor CNS access for polar aminosugar glycosides.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an anthracycline-like aminosugar glycoside with high polarity, high TPSA, and zwitterionic character. All high-transfer experimental analogues—glycosides, anthracycline-type agents, and P-gp substrates—show poor brain/CSF penetration, often due to efflux. Therefore the predicted CNS access is inadequate.",
  "evidence_gaps": [
    "No direct brain or CSF measurement for the exact query molecule",
    "No human pharmacokinetic data for the query",
    "Exact efflux transporter profile of the query is not experimentally confirmed"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

